  var steel=SportsEventAuthoring.Mat(Folder,"Target industrial rim",new Color(.14f,.18f,.23f),.45f);steel.SetFloat("_Metallic",.55f);var root=new GameObject("Floating scoring target").transform;root.position=new Vector3(0,4,130);m.target=root;var foundation=new GameObject("Modeled beveled physical target platform");foundation.transform.SetParent(root,false);foundation.transform.localScale=new Vector3(30,1,30);var baseMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckSumo/Models/Beveled continuous ring.asset");if(baseMesh==null)throw new Exception("Existing modeled sports platform required");foundation.AddComponent<MeshFilter>().sharedMesh=baseMesh;foundation.AddComponent<MeshRenderer>().sharedMaterial=steel;var board=foundation.AddComponent<MeshCollider>();board.sharedMesh=baseMesh;board.sharedMaterial=SportsEventAuthoring.Contact(Folder,"Physical target landing",.45f,.18f);m.targetCollider=board;
  var orange=SportsEventAuthoring.Mat(Folder,"Outer ten orange",new Color(.92f,.26f,.07f),.18f);var yellow=SportsEventAuthoring.Mat(Folder,"Middle twenty five gold",new Color(.98f,.71f,.13f),.18f);var blue=SportsEventAuthoring.Mat(Folder,"Precision fifty blue",new Color(.04f,.38f,.68f),.18f);var white=SportsEventAuthoring.Mat(Folder,"Hundred bullseye ivory",new Color(.96f,.94f,.78f),.18f);Disc(root,"Outer ten zone",30,.012f,orange);Disc(root,"Middle twenty five zone",18,.018f,yellow);m.precisionZones=new GameObject("Shared slowly moving precision zones").transform;m.precisionZones.SetParent(root,false);Disc(m.precisionZones,"Fifty point precision zone",8,.025f,blue);Disc(m.precisionZones,"Tiny hundred point bullseye",2.3f,.032f,white);
  Label(root,"10",new Vector3(0,.05f,-25),1.8f,Color.white);Label(root,"25",new Vector3(-12,.05f,-8),1.6f,new Color(.08f,.12f,.18f));Label(m.precisionZones,"50",new Vector3(0,.06f,-5.2f),1.4f,Color.white);Label(m.precisionZones,"100",new Vector3(0,.07f,0),.8f,new Color(.08f,.12f,.18f));m.landingMarkers=new Transform[4];for(int i=0;i<4;i++){var marker=new GameObject("Locked first-contact landing marker "+i);marker.transform.SetParent(root,false);marker.AddComponent<MeshFilter>().sharedMesh=MarkerMesh();marker.AddComponent<MeshRenderer>().sharedMaterial=white;marker.transform.localScale=Vector3.zero;m.landingMarkers[i]=marker.transform;}var floor=SportsEventAuthoring.Box("Far below crash ground",new Vector3(0,-16,100),new Vector3(600,1,600),SportsEventAuthoring.Mat(Folder,"Distant quarry floor",new Color(.24f,.28f,.3f),.08f),contact);m.missGround=floor.GetComponent<Collider>();
  var craneMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckBungeeDemolition/Models/Lattice Crane.asset");if(craneMesh!=null)for(int i=0;i<3;i++){var support=new GameObject("Reused modeled launch gantry "+i);support.transform.position=new Vector3(i%2==0?-14:14,-15,8+i*22);support.transform.localScale=Vector3.one*.65f;support.AddComponent<MeshFilter>().sharedMesh=craneMesh;support.AddComponent<MeshRenderer>().sharedMaterial=steel;}
  var quarry=new GameObject("Installed quarry cliffs and distant scale references").transform;for(int i=0;i<18;i++){float x=(i%2==0?-1:1)*(108+i%3*13),z=-10+(i/2)*28;LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(quarry,new Vector3(x,-15.5f,z),8+i%4*3,false,Folder);}
  var quarryStone=SportsEventAuthoring.Mat(Folder,"Slate quarry rock",new Color(.23f,.29f,.34f),.08f);foreach(var renderer in quarry.GetComponentsInChildren<MeshRenderer>())renderer.sharedMaterials=Enumerable.Repeat(quarryStone,renderer.sharedMaterials.Length).ToArray();
  m.racers=new TargetRacer[4];m.playerCameras=new SportsEventCamera[4];var wing=WingMesh();var wingMat=SportsEventAuthoring.Mat(Folder,"Ridiculous folding wing panels",new Color(.79f,.82f,.84f),.55f);wingMat.SetFloat("_Metallic",.65f);wingMat.SetFloat("_Cull",0);var flare=SportsChaosAuthoring.Flare(Folder);for(int i=0;i<4;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Target launch competitor "+(i+1),new Vector3((i-1.5f)*3,34.4f,2),i);SportsRallyAuthoring.FitTruck(t);t.maxSpeed=25;t.reverseSpeed=7;t.motorTorque=8;t.steerAngle=28;t.grip=1.35f;t.body.angularDamping=.18f;t.body.maxAngularVelocity=8;var assembly=new GameObject("Target render assembly").transform;assembly.SetParent(t.transform,false);t.visuals.SetParent(assembly,true);t.visuals=assembly;var racer=t.gameObject.AddComponent<TargetRacer>();racer.truck=t;racer.match=m;racer.slot=i;racer.wings=new Transform[2];for(int side=0;side<2;side++){var hinge=new GameObject("Foldable wing hinge "+side).transform;hinge.SetParent(assembly,false);hinge.localPosition=new Vector3(side==0?-.5f:.5f,.55f,-.45f);var model=new GameObject("Solid modeled wing panel");model.transform.SetParent(hinge,false);model.transform.localScale=new Vector3(side==0?-1:1,1,1);model.AddComponent<MeshFilter>().sharedMesh=wing;model.AddComponent<MeshRenderer>().sharedMaterial=wingMat;hinge.localRotation=Quaternion.Euler(0,0,side==0?-80:80);racer.wings[side]=hinge;}var fx=new GameObject("Pooled launch miss burst");fx.transform.SetParent(t.transform,false);racer.crash=fx.AddComponent<ParticleSystem>();SportsChaosAuthoring.FixBlast(racer.crash,flare);var main=racer.crash.main;main.simulationSpace=ParticleSystemSimulationSpace.World;racer.wind=t.gameObject.AddComponent<AudioSource>();racer.wind.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/WeatherMaker/Prefab/Sound/Wind/Wind1.wav");if(racer.wind.clip==null)racer.wind.clip=AssetDatabase.FindAssets("t:AudioClip",new[]{"Assets/WeatherMaker/Prefab/Sound"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.IndexOf("Wind",StringComparison.OrdinalIgnoreCase)>=0).Select(AssetDatabase.LoadAssetAtPath<AudioClip>).FirstOrDefault();racer.wind.loop=true;racer.wind.playOnAwake=false;m.racers[i]=racer;var camera=SportsEventAuthoring.Camera("Stable launch chase "+(i+1));camera.view.farClipPlane=700;camera.Pose(t.transform.position+Vector3.forward*9,new Vector3(0,3.5f,-8),65,true);camera.view.enabled=false;SportsRallyAuthoring.TuneCamera(camera);m.playerCameras[i]=camera;}
  m.broadcast=SportsEventAuthoring.Camera("Shared target launch broadcast");m.broadcast.view.farClipPlane=700;m.broadcast.Pose(new Vector3(0,32,18),new Vector3(27,23,-36),65,true);m.cameras=m.playerCameras.Select(c=>c.view).Concat(new[]{m.broadcast.view}).ToArray();m.atmosphere=SportsChaosAuthoring.Weather(m,Folder);m.atmosphere.Configure(m.seed,1,0);m.cameras=new[]{m.broadcast.view};m.replay=SportsRallyAuthoring.Replay(m,m.racers.Select(r=>r.truck.visuals).Concat(new[]{root}).ToArray());m.replay.capacity=1400;m.replay.interval=.05f;Cameras(m);SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);foreach(var t in m.menus.viewTexts){t.rectTransform.sizeDelta=new Vector2(790,100);t.fontSizeMax=22;t.fontSizeMin=18;t.transform.parent.Find("View data backing").GetComponent<RectTransform>().sizeDelta=new Vector2(810,120);}TargetRepairAuthoring.Install(m);TargetPreviewAuthoring.Create(m);SportsEventAuthoring.Save(Folder);Validate();
 }
 static void Cameras(TargetMatch m){var director=m.gameObject.AddComponent<TargetCameras>();m.director=director;director.match=m;director.rim=new Transform[8];director.ghostRim=new Transform[8];for(int i=0;i<8;i++){float a=i*Mathf.PI*.25f;var live=new GameObject("Framing rim anchor "+i).transform;live.SetParent(m.target,false);live.localPosition=new Vector3(Mathf.Sin(a)*30,.5f,Mathf.Cos(a)*30);director.rim[i]=live;var ghost=new GameObject("Framing rim anchor "+i).transform;ghost.SetParent(m.replay.ghosts[4],false);ghost.localPosition=live.localPosition;director.ghostRim[i]=ghost;}director.groups=new CinemachineTargetGroup[5];for(int i=0;i<5;i++){var camera=i<4?m.playerCameras[i]:m.broadcast;var group=new GameObject("Owned Cinemachine framing group "+i).AddComponent<CinemachineTargetGroup>();group.m_RotationMode=CinemachineTargetGroup.RotationMode.Manual;group.m_PositionMode=CinemachineTargetGroup.PositionMode.GroupCenter;group.m_Targets=new CinemachineTargetGroup.Target[i<4?9:12];int offset=i<4?1:4;for(int n=0;n<offset;n++)group.m_Targets[n]=new CinemachineTargetGroup.Target{target=m.racers[i<4?i:n].truck.transform,weight=1,radius=2};for(int n=0;n<8;n++)group.m_Targets[n+offset]=new CinemachineTargetGroup.Target{target=director.rim[n],weight=0,radius=.5f};camera.rig.Follow=camera.rig.LookAt=group.transform;var old=camera.rig.GetCinemachineComponent<CinemachineComposer>();if(old!=null)UnityEngine.Object.DestroyImmediate(old);var composer=camera.rig.AddCinemachineComponent<CinemachineGroupComposer>();composer.m_FramingMode=CinemachineGroupComposer.FramingMode.HorizontalAndVertical;composer.m_AdjustmentMode=CinemachineGroupComposer.AdjustmentMode.DollyOnly;composer.m_GroupFramingSize=.78f;composer.m_FrameDamping=.45f;composer.m_MinimumDistance=8;composer.m_MaximumDistance=400;composer.m_MaxDollyOut=400;composer.m_ScreenY=.42f;composer.m_DeadZoneWidth=composer.m_DeadZoneHeight=0;composer.m_SoftZoneWidth=composer.m_SoftZoneHeight=.05f;director.groups[i]=group;}}
 static void Label(Transform parent,string text,Vector3 local,float size,Color color){
  // Bake installed TMP glyph geometry: both live target and render-only replay
  // retain identical inlaid numbers without a camera-facing text component.
  var temporary=new GameObject("Bake score glyphs").AddComponent<TextMeshPro>();temporary.font=TMP_Settings.defaultFontAsset;temporary.fontSize=48;temporary.text=text;temporary.color=color;temporary.alignment=TextAlignmentOptions.Center;temporary.rectTransform.sizeDelta=new Vector2(20,10);temporary.ForceMeshUpdate();var glyphs=temporary.mesh;var vertices=glyphs.vertices;float scale=size*2/Mathf.Max(.01f,glyphs.bounds.size.y);for(int i=0;i<vertices.Length;i++)vertices[i]=(vertices[i]-glyphs.bounds.center)*scale;var mesh=Mesh("Inlaid score glyphs "+text,vertices,glyphs.triangles,glyphs.uv);mesh.colors32=glyphs.colors32;mesh.uv2=glyphs.uv2;mesh.tangents=glyphs.tangents;EditorUtility.SetDirty(mesh);var label=new GameObject("Inlaid score "+text);label.transform.SetParent(parent,false);label.transform.localPosition=local;label.transform.localRotation=Quaternion.Euler(90,0,0);label.AddComponent<MeshFilter>().sharedMesh=mesh;label.AddComponent<MeshRenderer>().sharedMaterial=temporary.fontSharedMaterial;UnityEngine.Object.DestroyImmediate(temporary.gameObject);
 }
 static void Disc(Transform parent,string name,float radius,float height,Material material){const int n=128;var vertices=new Vector3[n+2];var uv=new Vector2[n+2];var indices=new int[n*3];vertices[0]=Vector3.up*height;uv[0]=Vector2.one*.5f;for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;vertices[i+1]=new Vector3(Mathf.Sin(a)*radius,height,Mathf.Cos(a)*radius);uv[i+1]=new Vector2(Mathf.Sin(a),Mathf.Cos(a))*.5f+Vector2.one*.5f;if(i<n){indices[i*3]=0;indices[i*3+1]=i+1;indices[i*3+2]=i+2;}}var mesh=Mesh(name,vertices,indices,uv);var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;}
 static Mesh MarkerMesh(){var vertices=new List<Vector3>();var indices=new List<int>();for(int i=0;i<4;i++){var q=Quaternion.Euler(0,i*90,0);int n=vertices.Count;vertices.Add(q*new Vector3(-.22f,0,1.3f));vertices.Add(q*new Vector3(.22f,0,1.3f));vertices.Add(q*new Vector3(0,0,.7f));indices.AddRange(new[]{n,n+1,n+2});}return Mesh("Scored landing chevrons",vertices.ToArray(),indices.ToArray(),vertices.Select(v=>new Vector2(v.x,v.z)).ToArray());}
 static Mesh WingMesh(){var polygon=new[]{new Vector3(0,0,-.48f),new Vector3(1.35f,.04f,-.15f),new Vector3(1.05f,.04f,.32f),new Vector3(0,0,.45f)};var vertices=polygon.Select(p=>p+Vector3.up*.025f).Concat(polygon.Select(p=>p-Vector3.up*.025f)).ToArray();var indices=new List<int>{0,2,1,0,3,2,4,5,6,4,6,7};for(int i=0;i<4;i++){int j=(i+1)%4;indices.AddRange(new[]{i,j,i+4,j,j+4,i+4});}return Mesh("Folded solid miniature wings",vertices,indices.ToArray(),vertices.Select(p=>new Vector2(p.x,p.z)).ToArray());}
 static Mesh Mesh(string name,Vector3[] vertices,int[] indices,Vector2[] uv){string path="Assets/"+Folder+"/Models/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name=name};AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=vertices;mesh.uv=uv;mesh.triangles=indices;mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);return mesh;}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<TargetMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<TargetMatch>();}if(m==null||m.racers.Length!=4||m.targetCollider==null||m.target.localScale!=Vector3.one||m.playerCameras.Length!=4||m.replay.sources.Length!=9||m.atmosphere==null||m.volcano==null||m.scoreFeedback==null||m.volcano.wrecks.pieces.Length!=48)throw new Exception("Target scene references incomplete");foreach(var r in m.racers)if(r.wings.Length!=2||r.wind.clip==null||r.truck.visuals.GetComponentsInChildren<Collider>(true).Length!=0)throw new Exception("Target flight presentation/control references incomplete");Debug.Log("TARGET_NATIVE_SCENE_VALIDATED");}
